//! What one shadcn style says about one component part. The types are
//! hand-written; the values are generated by `tools/stylegen` from the
//! part's full class string: the svelte component's own classes with the
//! style's `@apply` classes (`style-<s>.css`) in place of its `cn-*` marker.
//! Every field is a [`Prop`]: an optional base value plus rules that apply
//! under state and context conditions, the way a Tailwind class applies
//! under its variants. An empty `Prop` means upstream sets nothing; the
//! component then uses the inherited or initial value.

use std::ops::BitOr;

/// State and context flags. A component builds one per paint; the theme adds
/// [`State::DARK`]. Each flag stands for the Tailwind variants listed.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct State(pub u32);

impl State {
    pub const NONE: State = State(0);
    /// `dark:`
    pub const DARK: State = State(1 << 0);
    /// `hover:`
    pub const HOVER: State = State(1 << 1);
    /// `focus:`, `data-highlighted:` (the highlighted item of a list)
    pub const FOCUS: State = State(1 << 2);
    /// `focus-visible:` (keyboard focus)
    pub const FOCUS_VISIBLE: State = State(1 << 3);
    /// `active:` (pressed)
    pub const ACTIVE: State = State(1 << 4);
    /// `disabled:`, `data-disabled:`, `group-data-[disabled=true]:`, `peer-disabled:`
    pub const DISABLED: State = State(1 << 5);
    /// `aria-invalid:`, `data-invalid:`
    pub const INVALID: State = State(1 << 6);
    /// `data-checked:`, `aria-checked:`, `data-[state=checked]:`
    pub const CHECKED: State = State(1 << 7);
    /// `data-unchecked:`, `data-[state=unchecked]:`
    pub const UNCHECKED: State = State(1 << 8);
    /// `aria-expanded:`
    pub const EXPANDED: State = State(1 << 9);
    /// `aria-[haspopup]:` (used negated: `not-aria-[haspopup]:`)
    pub const HAS_POPUP: State = State(1 << 10);
    /// `data-active:`, `data-[active=true]:`, `data-selected:`
    pub const SELECTED: State = State(1 << 11);
    /// `data-placeholder:`, `placeholder:` (placeholder text shows)
    pub const PLACEHOLDER: State = State(1 << 12);
    /// `has-data-[icon=inline-start]:`
    pub const ICON_START: State = State(1 << 16);
    /// `has-data-[icon=inline-end]:`
    pub const ICON_END: State = State(1 << 17);
    /// `in-data-[slot=button-group]:`
    pub const IN_BUTTON_GROUP: State = State(1 << 18);
    /// `data-[size=sm]:`, `group-data-[size=sm]/…:`
    pub const SIZE_SM: State = State(1 << 19);
    /// `data-[size=default]:`, `group-data-[size=default]/…:`
    pub const SIZE_DEFAULT: State = State(1 << 20);
    /// `data-vertical:`, `data-[orientation=vertical]:`, `group-data-vertical/…:`
    pub const VERTICAL: State = State(1 << 21);
    /// `data-horizontal:`, `data-[orientation=horizontal]:`, `group-data-horizontal/…:`
    pub const HORIZONTAL: State = State(1 << 22);
    /// `data-[variant=line]:`, `group-data-[variant=line]/…:`
    pub const VARIANT_LINE: State = State(1 << 23);
    /// `group-data-[variant=default]/…:`
    pub const VARIANT_DEFAULT: State = State(1 << 24);
    /// `has-data-[slot=card-footer]:`
    pub const HAS_FOOTER: State = State(1 << 25);

    pub const fn or(self, other: State) -> State {
        State(self.0 | other.0)
    }
    pub const fn with(self, flag: State, on: bool) -> State {
        if on {
            self.or(flag)
        } else {
            self
        }
    }
    pub const fn contains(self, other: State) -> bool {
        self.0 & other.0 == other.0
    }
}

impl BitOr for State {
    type Output = State;
    fn bitor(self, rhs: State) -> State {
        self.or(rhs)
    }
}

/// The condition of a rule: every flag in `all` set, no flag in `none` set.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct When {
    pub all: State,
    pub none: State,
}

impl When {
    pub const ALWAYS: When = When {
        all: State::NONE,
        none: State::NONE,
    };
    pub const fn new(all: State, none: State) -> When {
        When { all, none }
    }
    /// Matches when every flag in `all` is set, whatever else is.
    pub const fn all(all: State) -> When {
        When {
            all,
            none: State::NONE,
        }
    }
    pub fn matches(self, s: State) -> bool {
        s.contains(self.all) && s.0 & self.none.0 == 0
    }
}

/// A value that applies when `when` matches. When several rules match, the
/// highest `rank` wins, as in the browser's cascade of shadcn's CSS. The
/// rank packs, from the top: bit 127 for an `!important` class, which beats
/// every normal one; bit 126 for a `placeholder:` class, as the
/// placeholder's own rule beats what it inherits from the part; the count of
/// classes, attributes and pseudo-classes the variants add to the
/// specificity, one `1 << 122` each (bits 122 to 125); bit 121, a half
/// step, which `[&_svg:not([class*='size-'])]:` adds where `[&>svg]:` adds
/// nothing (more specific, but it loses a tie of equal specificity to
/// `[&>svg]:`); and below that the Tailwind v4 variant-order bitmask, one
/// bit per distinct variant, which decides between equal ranks above.
///
/// To rank an app's rule like a generated one, OR the variant bits taken
/// from a generated rule with the same variants, then add `1 << 122` per
/// state variant (`hover:`, `dark:`, `data-*:`, `aria-*:`, `group-*:`,
/// `peer-*:`, `has-*:`, `not-*:`), `1 << 121` for
/// `[&_svg:not([class*='size-'])]:`, nothing for `sm:`, `md:`,
/// `supports-*:`, `in-*:`, `after:` and `[&>svg]:` (which have no variant
/// bit either), and `1 << 126` for `placeholder:`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rule<T> {
    pub when: When,
    pub rank: u128,
    pub value: T,
}

impl<T> Rule<T> {
    /// The rank bit of an `!important` class (`bg-primary!`). A rule with
    /// it beats every rule without it that also matches, whatever their
    /// variants. Spell it `Rule::<Paint>::IMPORTANT` (any `T`).
    pub const IMPORTANT: u128 = 1 << 127;

    /// An app's override, ranked like a Tailwind `!` class: it beats every
    /// generated rule that is not important. Against an upstream `!` class
    /// of the same rank it wins because it comes later in the rule list; an
    /// upstream `!` class that also names a state ranks higher and still
    /// wins.
    ///
    /// ```
    /// use std::sync::Arc;
    /// use shadcn_egui::style::{pick, Paint, Role, Rule, State, When};
    /// let mut theme = shadcn_egui::Theme::vega_light();
    /// let style = Arc::make_mut(&mut theme.style);
    /// let primary = Paint::Role(Role::Primary, 1.0);
    /// let selected_hover = State::SELECTED | State::HOVER;
    /// let bg = |s: &shadcn_egui::style::Style, st| pick(&[&*s.tabs_trigger], |r| &r.bg, st);
    /// assert_ne!(bg(style, selected_hover), Some(primary));
    /// style.tabs_trigger.bg.rules.push(Rule::important(
    ///     When::all(State::SELECTED),
    ///     primary,
    /// ));
    /// // The override wins over every generated rule that matches.
    /// assert_eq!(bg(style, selected_hover), Some(primary));
    /// // Where its condition does not match, the generated value stays.
    /// assert_ne!(bg(style, State::HOVER), Some(primary));
    /// ```
    pub fn important(when: When, value: T) -> Rule<T> {
        Rule {
            when,
            rank: Self::IMPORTANT,
            value,
        }
    }
}

/// One property of a recipe. Set `base` to change the unconditional value;
/// push a [`Rule`] to add a conditional one.
///
/// A value that applies always can also sit in a [`When::ALWAYS`] rule
/// with a rank above 0: every generated `icon_size` does, as its svg target
/// adds to the rank. Such a rule beats `base`, so setting `base` there
/// changes nothing; assign `Prop::fixed(value)` to replace the property:
///
/// ```
/// use shadcn_egui::style::{pick, Prop, State};
/// let mut style = shadcn_egui::Style::vega();
/// let icon = |s: &shadcn_egui::Style| {
///     pick(&[&*s.button, &*s.button_variant_default], |r| &r.icon_size, State::NONE)
/// };
/// style.button.icon_size.base = Some(20.0);
/// assert_eq!(icon(&style), Some(16.0));
/// style.button.icon_size = Prop::fixed(20.0);
/// assert_eq!(icon(&style), Some(20.0));
/// ```
#[derive(Clone, Debug, PartialEq)]
pub struct Prop<T> {
    pub base: Option<T>,
    pub rules: Vec<Rule<T>>,
}

impl<T> Default for Prop<T> {
    fn default() -> Self {
        Prop {
            base: None,
            rules: Vec::new(),
        }
    }
}

impl<T: Copy> Prop<T> {
    pub fn fixed(value: T) -> Self {
        Prop {
            base: Some(value),
            rules: Vec::new(),
        }
    }
    pub fn get(&self, s: State) -> Option<T> {
        pick_props([self], s)
    }
}

/// Resolve one property across stacked recipes, in the order upstream joins
/// their classes (e.g. `cn-button`, then `cn-button-variant-*`, then
/// `cn-button-size-*`). The matching candidate with the highest rank wins;
/// ties go to the later layer, then the later rule. A base value has rank 0.
pub fn pick<T: Copy>(
    layers: &[&Recipe],
    field: impl Fn(&Recipe) -> &Prop<T>,
    s: State,
) -> Option<T> {
    pick_props(layers.iter().map(|r| field(r)), s)
}

/// Like [`pick`], but also the condition of the winning candidate: the
/// rule's [`When`], or [`When::ALWAYS`] for a base value.
pub(crate) fn pick_when<T: Copy>(
    layers: &[&Recipe],
    field: impl Fn(&Recipe) -> &Prop<T>,
    s: State,
) -> Option<(When, T)> {
    pick_props_when(layers.iter().map(|r| field(r)), s)
}

fn pick_props<'a, T: Copy + 'a>(
    props: impl IntoIterator<Item = &'a Prop<T>>,
    s: State,
) -> Option<T> {
    pick_props_when(props, s).map(|(_, v)| v)
}

fn pick_props_when<'a, T: Copy + 'a>(
    props: impl IntoIterator<Item = &'a Prop<T>>,
    s: State,
) -> Option<(When, T)> {
    let mut best: Option<((u128, usize, usize), When, T)> = None;
    let mut consider = |key: (u128, usize, usize), when: When, v: T| {
        if best.as_ref().is_none_or(|(k, _, _)| key >= *k) {
            best = Some((key, when, v));
        }
    };
    for (li, p) in props.into_iter().enumerate() {
        if let Some(v) = p.base {
            consider((0, li, 0), When::ALWAYS, v);
        }
        for (ri, r) in p.rules.iter().enumerate() {
            if r.when.matches(s) {
                consider((r.rank, li, ri + 1), r.when, r.value);
            }
        }
    }
    best.map(|(_, when, v)| (when, v))
}

/// A palette colour role (shadcn CSS variable), or a fixed colour.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum Role {
    Background,
    Foreground,
    Card,
    CardForeground,
    Popover,
    PopoverForeground,
    Primary,
    PrimaryForeground,
    Secondary,
    SecondaryForeground,
    Muted,
    MutedForeground,
    Accent,
    AccentForeground,
    Destructive,
    DestructiveForeground,
    Border,
    Input,
    Ring,
    White,
    Black,
    Transparent,
}

/// A colour as a style states it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Paint {
    /// `bg-primary/80` → `Role(Primary, 0.8)`.
    Role(Role, f32),
    /// `color-mix(in oklch, a, b t)`: `t` is the share of `b`.
    Mix(Role, Role, f32),
}

/// A step of shadcn's radius scale, multiplied from the theme radius
/// (`sm` ×0.6, `md` ×0.8, `lg` ×1, `xl` ×1.4, `2xl` ×1.8, `3xl` ×2.2, `4xl` ×2.6).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Rung {
    None,
    Sm,
    Md,
    Lg,
    Xl,
    Xl2,
    Xl3,
    Xl4,
    Full,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Radius {
    Rung(Rung),
    Px(f32),
    /// `rounded-[min(var(--radius-md),10px)]`
    Min(Rung, f32),
}

/// `text-xs` … `text-lg`, resolved through `Metrics`; or an arbitrary size.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum TextSize {
    Xs,
    Sm,
    Base,
    Lg,
    Px(f32),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Weight {
    Normal,
    Medium,
    Semibold,
    Bold,
}

/// Tailwind v4 `shadow-*` levels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ShadowLevel {
    None,
    Xs2,
    Xs,
    Sm,
    Md,
    Lg,
    Xl,
    Xl2,
}

/// A translation: fixed pixels, or `calc(100% - Npx)` of the part's own size.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Shift {
    Px(f32),
    SelfMinus(f32),
}

/// Everything a style can say about one part. Lengths are logical px.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Recipe {
    pub height: Prop<f32>,
    pub width: Prop<f32>,
    pub min_height: Prop<f32>,
    pub min_width: Prop<f32>,
    pub max_width: Prop<f32>,
    /// `max-w-[calc(100%-Npx)]`: keep N px clear of the parent's width.
    pub max_width_inset: Prop<f32>,
    /// `h-[calc(100%-Npx)]`: the parent's content height minus N px.
    pub height_inset: Prop<f32>,
    pub pad_top: Prop<f32>,
    pub pad_right: Prop<f32>,
    pub pad_bottom: Prop<f32>,
    pub pad_left: Prop<f32>,
    pub margin_top: Prop<f32>,
    pub margin_right: Prop<f32>,
    pub margin_bottom: Prop<f32>,
    pub margin_left: Prop<f32>,
    pub gap: Prop<f32>,
    /// `top-N` etc. of an absolutely placed part (dialog close button).
    pub inset_top: Prop<f32>,
    pub inset_right: Prop<f32>,
    pub inset_bottom: Prop<f32>,
    pub inset_left: Prop<f32>,
    /// `[&_svg:not([class*='size-'])]:size-N` and `[&>svg]:size-N`.
    pub icon_size: Prop<f32>,
    pub text_size: Prop<TextSize>,
    /// `leading-*` as a multiple of the font size.
    pub line_height: Prop<f32>,
    /// `tracking-*` in em.
    pub tracking: Prop<f32>,
    pub weight: Prop<Weight>,
    pub uppercase: Prop<bool>,
    pub underline: Prop<bool>,
    pub radius: Prop<Radius>,
    pub radius_top: Prop<Radius>,
    pub radius_bottom: Prop<Radius>,
    pub bg: Prop<Paint>,
    /// `bg-clip-padding`: the fill stops inside the border, so a transparent
    /// border shows what lies under the part.
    pub bg_clip_padding: Prop<bool>,
    pub text: Prop<Paint>,
    pub border_width: Prop<f32>,
    pub border_top_width: Prop<f32>,
    pub border_color: Prop<Paint>,
    pub ring_width: Prop<f32>,
    pub ring_color: Prop<Paint>,
    /// `outline-N`: an outline N px wide just outside the border box
    /// (`outline-none`, `outline-hidden`: 0).
    pub outline_width: Prop<f32>,
    pub outline_color: Prop<Paint>,
    pub shadow: Prop<ShadowLevel>,
    pub opacity: Prop<f32>,
    pub shift_x: Prop<Shift>,
    /// `active:translate-y-px` is the press nudge.
    pub shift_y: Prop<Shift>,
    /// `after:-inset-x-N`: hit area grows N px left and right.
    pub hit_inset_x: Prop<f32>,
    pub hit_inset_y: Prop<f32>,
    /// `backdrop-blur-*` in px.
    pub backdrop_blur: Prop<f32>,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rule<T>(all: State, rank: u128, value: T) -> Rule<T> {
        Rule {
            when: When::new(all, State::NONE),
            rank,
            value,
        }
    }

    #[test]
    fn important_rule_beats_every_normal_rule() {
        // dark:data-active:bg-input/30 has two high variant bits; an app's
        // important rule under SELECTED alone still wins.
        let mut p = Prop {
            base: Some(0),
            rules: vec![rule(
                State::DARK.or(State::SELECTED),
                (1 << 120) | (1 << 100),
                1,
            )],
        };
        p.rules.push(Rule::important(When::all(State::SELECTED), 2));
        assert_eq!(p.get(State::DARK | State::SELECTED), Some(2));
        assert_eq!(p.get(State::DARK), Some(0));
        // An upstream `!` class without variants (luma `border-transparent!`)
        // has the same rank: the later rule, the app's, wins.
        let mut q = Prop {
            base: None,
            rules: vec![rule(State::NONE, Rule::<i32>::IMPORTANT, 1)],
        };
        q.rules.push(Rule::important(When::all(State::SELECTED), 2));
        assert_eq!(q.get(State::SELECTED), Some(2));
        assert_eq!(q.get(State::NONE), Some(1));
    }

    #[test]
    fn when_all_needs_every_flag() {
        let w = When::all(State::SELECTED | State::DARK);
        assert!(w.matches(State::SELECTED | State::DARK | State::HOVER));
        assert!(!w.matches(State::SELECTED));
        assert_eq!(w.none, State::NONE);
    }

    #[test]
    fn base_applies_without_rules() {
        let p = Prop::fixed(32.0);
        assert_eq!(p.get(State::NONE), Some(32.0));
        assert_eq!(Prop::<f32>::default().get(State::HOVER), None);
    }

    #[test]
    fn matching_rule_beats_base() {
        let p = Prop {
            base: Some(10.0),
            rules: vec![rule(State::ICON_START, 1 << 14, 8.0)],
        };
        assert_eq!(p.get(State::NONE), Some(10.0));
        assert_eq!(p.get(State::ICON_START), Some(8.0));
    }

    #[test]
    fn higher_rank_wins_over_later_rule() {
        // dark:bg-input/30 (rank DARK) and hover:bg-muted (rank HOVER): dark
        // is registered later in Tailwind, so it wins when both match.
        let p = Prop {
            base: None,
            rules: vec![rule(State::DARK, 1 << 20, 1), rule(State::HOVER, 1 << 8, 2)],
        };
        assert_eq!(p.get(State::DARK | State::HOVER), Some(1));
        // dark:hover: has both bits, so it beats dark: alone.
        let mut p2 = p.clone();
        p2.rules
            .push(rule(State::DARK | State::HOVER, (1 << 20) | (1 << 8), 3));
        assert_eq!(p2.get(State::DARK | State::HOVER), Some(3));
    }

    #[test]
    fn two_variants_of_one_kind_beat_one() {
        // cn-checkbox: aria-invalid:aria-checked:border-primary must beat
        // aria-invalid:border-destructive when the box is invalid and
        // checked. Each variant has its own bit (stylegen ranks: aria-checked
        // 26, aria-invalid 28), so the pair's mask is larger.
        let p = Prop {
            base: Some(0),
            rules: vec![
                rule(State::INVALID.or(State::CHECKED), (1 << 26) | (1 << 28), 1),
                rule(State::INVALID, 1 << 28, 2),
            ],
        };
        assert_eq!(p.get(State::INVALID | State::CHECKED), Some(1));
        assert_eq!(p.get(State::INVALID), Some(2));
    }

    #[test]
    fn specificity_beats_variant_order() {
        // data-[size=sm]:h-7 (one attribute) against md:h-9 (no
        // specificity): Tailwind emits md: later (a higher variant bit), the
        // browser picks the more specific h-7.
        let p = Prop {
            base: None,
            rules: vec![
                rule(State::SIZE_SM, (1 << 34) | (1 << 122), 28.0),
                rule(State::NONE, 1 << 50, 36.0),
            ],
        };
        assert_eq!(p.get(State::SIZE_SM), Some(28.0));
        assert_eq!(p.get(State::NONE), Some(36.0));
        // Two classes beat one whatever the variant bits; important beats
        // both.
        let mut q = Prop {
            base: None,
            rules: vec![
                rule(
                    State::DARK.or(State::HOVER),
                    (1 << 0) | (1 << 1) | (2 << 122),
                    1.0,
                ),
                rule(State::DARK, (1 << 120) | (1 << 122), 2.0),
            ],
        };
        assert_eq!(q.get(State::DARK | State::HOVER), Some(1.0));
        // A placeholder: rule (bit 126) beats the part's own rules
        // whatever their classes.
        q.rules
            .push(rule(State::PLACEHOLDER, (1 << 16) | (1 << 126), 4.0));
        assert_eq!(
            q.get(State::DARK | State::HOVER | State::PLACEHOLDER),
            Some(4.0)
        );
        q.rules.push(Rule::important(When::ALWAYS, 3.0));
        assert_eq!(
            q.get(State::DARK | State::HOVER | State::PLACEHOLDER),
            Some(3.0)
        );
    }

    #[test]
    fn ranks_use_all_128_bits() {
        let p = Prop {
            base: None,
            rules: vec![
                rule(State::DARK, 1 << 127, 1),
                rule(State::DARK, (1 << 126) | 1, 2),
            ],
        };
        assert_eq!(p.get(State::DARK), Some(1));
    }

    #[test]
    fn negated_condition() {
        let p = Prop {
            base: None,
            rules: vec![Rule {
                when: When::new(State::ACTIVE, State::HAS_POPUP),
                rank: 1,
                value: true,
            }],
        };
        assert_eq!(p.get(State::ACTIVE), Some(true));
        assert_eq!(p.get(State::ACTIVE | State::HAS_POPUP), None);
    }

    #[test]
    fn later_layer_wins_ties() {
        let button = Recipe {
            height: Prop::fixed(1.0),
            ..Recipe::default()
        };
        let size = Recipe {
            height: Prop::fixed(32.0),
            ..Recipe::default()
        };
        assert_eq!(
            pick(&[&button, &size], |r| &r.height, State::NONE),
            Some(32.0)
        );
        // A conditional rule in an earlier layer still beats a later base.
        let button = Recipe {
            height: Prop {
                base: None,
                rules: vec![rule(State::SIZE_SM, 1 << 16, 20.0)],
            },
            ..Recipe::default()
        };
        assert_eq!(
            pick(&[&button, &size], |r| &r.height, State::SIZE_SM),
            Some(20.0)
        );
    }

    #[test]
    fn consumer_can_override_base() {
        let mut r = Recipe {
            height: Prop::fixed(32.0),
            ..Recipe::default()
        };
        r.height.base = Some(40.0);
        assert_eq!(r.height.get(State::HOVER), Some(40.0));
    }
}
